import styles from "./header.module.less";
import { useEffect, useState, useCallback, useRef } from "react";
import HeaderProps from "@/core/components/modules/header/header-types";
import HeaderActions from "@/core/components/modules/header/header-actions/header-actions";
import HeaderOverlays from "@/core/components/modules/header/header-overlays/header-overlays";
import { EventAggregator, modalStackManager } from "@/core/helpers";

const Header = ({
  siteName,
  siteLogo,
  menuLogo: menuLogoProp,
  siteMenuLinkGroups,
  siteConfig,
  isStartPage,
  disableCart = false,
  contextValues,
  setContextValues,
  loginLink,
  languageSelectionList,
  siteMenuBackgroundPatternUrls,
}: HeaderProps) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const actionButtonRef = useRef<HTMLButtonElement | null>(null);
  const logoUrl = siteLogo.internalLink?.slug;
  const logoImageUrl = siteLogo.image?.file.url;
  const menuLogo =
    menuLogoProp?.gatsbyImageData ||
    menuLogoProp?.file?.url ||
    siteConfig.footerLogo?.gatsbyImageData ||
    siteConfig.footerLogo?.file?.url;

  const setActionButtonRef = useCallback((btn: HTMLButtonElement | null) => {
    actionButtonRef.current = btn;
  }, []);

  const focusHeaderActionButton = () => {
    actionButtonRef.current?.focus();
  };

  const toggleCart = useCallback(() => {
    const newShowCart = !contextValues.showCart;
    setContextValues({
      showCart: newShowCart,
      ...(newShowCart ? {} : { isMainVisible: true }),
    });
  }, [contextValues.showCart, setContextValues]);

  const toggleMore = useCallback(() => {
    const newShowMenu = !contextValues.showMenu;
    setContextValues({
      showMenu: newShowMenu,
      ...(newShowMenu ? {} : { isMainVisible: true }),
    });
  }, [contextValues.showMenu, setContextValues]);

  const toggleSearch = useCallback(() => {
    const newShowSearch = !contextValues.showSearch;
    setContextValues({
      showSearch: newShowSearch,
      ...(newShowSearch ? {} : { isMainVisible: true }),
    });
  }, [contextValues.showSearch, setContextValues]);

  const closeMenu = useCallback(() => {
    setContextValues({
      showMenu: false,
      showCart: false,
      showSearch: false,
      isMainVisible: true,
    });

    focusHeaderActionButton();
  }, [setContextValues]);

  useEffect(() => {
    const handleScroll = () => {
      // Ignore scroll events when any modal is open
      const anyOpenModal = modalStackManager.isAnyModalOpen();
      if (anyOpenModal) {
        return;
      }

      const scrollY = window.scrollY;

      // Use hysteresis (different thresholds for transitioning up vs down) to avoid "twitching"
      setIsScrolled((prevIsScrolled) => {
        if (!prevIsScrolled && scrollY > 70) {
          return true;
        } else if (prevIsScrolled && scrollY < 30) {
          return false;
        }
        return prevIsScrolled;
      });
    };

    const onScrollSubscription = EventAggregator.subscribe("onScroll", handleScroll);

    handleScroll();

    return () => onScrollSubscription.remove();
  }, []);

  return (
    <header className={styles.header} data-header-size={isScrolled ? "reduced" : undefined}>
      <HeaderActions
        languageSelectionList={languageSelectionList}
        disableCart={disableCart}
        closeMenu={closeMenu}
        toggleSearch={toggleSearch}
        toggleCart={toggleCart}
        toggleMore={toggleMore}
        setActionButtonRef={setActionButtonRef}
        siteName={siteName}
        logoUrl={logoUrl}
        logoImageUrl={logoImageUrl}
      />
      <HeaderOverlays
        disableCart={disableCart}
        contextValues={contextValues}
        closeMenu={closeMenu}
        menuLogo={menuLogo}
        siteName={siteName}
        isStartPage={isStartPage}
        logoUrl={logoUrl}
        loginLink={loginLink}
        siteMenuLinkGroups={siteMenuLinkGroups}
        siteMenuBackgroundPatternUrls={siteMenuBackgroundPatternUrls}
        setContextValues={setContextValues}
      />
    </header>
  );
};

export default Header;
