import styles from "./header-overlays.module.less";
import FullPageOverlay from "@/core/components/primitives/full-page-overlay/full-page-overlay";
import { ContextValues, LinkGroup } from "@/core/components/modules/header/header-types";
import { EventAggregator } from "@/core/helpers";
import { IGatsbyImageData } from "gatsby-plugin-image";
import LunrSearch from "@/core/components/modules/header/lunr-search/lunr-search";
import SiteMenu from "@/core/components/modules/header/site-menu/site-menu";
import { ShopServiceCart } from "@/core/components/modules/cart/shop-service-cart";
import { useTranslation } from "react-i18next";

/** Renders overlays for the menu, cart, and search. */
const HeaderOverlays = ({
  disableCart,
  contextValues,
  menuLogo,
  siteName,
  isStartPage,
  logoUrl,
  loginLink,
  siteMenuLinkGroups,
  siteMenuBackgroundPatternUrls,
  closeMenu,
  setContextValues,
}: {
  disableCart: boolean;
  contextValues: ContextValues;
  menuLogo?: string | IGatsbyImageData;
  siteName: string;
  isStartPage: boolean;
  logoUrl?: string;
  loginLink?: JSX.Element;
  siteMenuLinkGroups?: LinkGroup[];
  siteMenuBackgroundPatternUrls?: {
    default: string;
    highQuality: string;
    lowQuality: string;
  };
  closeMenu: () => void;
  setContextValues: (values: Partial<ContextValues>) => void;
}) => {
  const cssVariables = {
    "--image-url-default": siteMenuBackgroundPatternUrls?.default && `url(${siteMenuBackgroundPatternUrls?.default})`,
    "--image-url-high-quality":
      siteMenuBackgroundPatternUrls?.highQuality && `url(${siteMenuBackgroundPatternUrls?.highQuality})`,
    "--image-url-low-quality":
      siteMenuBackgroundPatternUrls?.lowQuality && `url(${siteMenuBackgroundPatternUrls?.lowQuality})`,
  } as React.CSSProperties;

  const { t } = useTranslation();

  const handleOnClose = (label: string) => () => {
    EventAggregator.publish("trackEvent", {
      category: "Header",
      action: "Closed",
      label: label,
    });
    closeMenu();
  };

  return (
    <>
      {contextValues.showMenu && (
        <FullPageOverlay
          open={contextValues.showMenu}
          onClose={handleOnClose("Site Menu")}
          id="site-menu"
          pageName={t("menu")}
          focusOnCloseButton
        >
          <div
            className={styles.overlayContentWrapper}
            data-has-image={!!siteMenuBackgroundPatternUrls}
            style={cssVariables}
          >
            <SiteMenu
              siteMenuLogo={menuLogo}
              siteName={siteName}
              isStartPage={isStartPage}
              logoUrl={logoUrl}
              hasBackgroundImage={!!siteMenuBackgroundPatternUrls}
              loginLink={loginLink}
              linkGroups={siteMenuLinkGroups}
              closeMenu={closeMenu}
            />
          </div>
        </FullPageOverlay>
      )}
      {!disableCart && contextValues.showCart && (
        <FullPageOverlay
          open={contextValues.showCart}
          onClose={handleOnClose("Cart")}
          id="cart"
          pageName={t("cart")}
          focusOnCloseButton
        >
          <div className={styles.overlayContentWrapper}>
            <ShopServiceCart
              onGoToCheckout={() => {
                closeMenu();
                EventAggregator.publish("trackEvent", {
                  category: "Header",
                  action: "Clicked",
                  label: "Checkout",
                });
              }}
              onContinueShopping={() => {
                closeMenu();
                EventAggregator.publish("trackEvent", {
                  category: "Header",
                  action: "Closed",
                  label: "Cart",
                });
              }}
            />
          </div>
        </FullPageOverlay>
      )}
      {contextValues.showSearch && (
        <FullPageOverlay
          open={contextValues.showSearch}
          onClose={handleOnClose("Search")}
          id="search"
          pageName={t("search")}
        >
          <div className={styles.overlayContentWrapper}>
            <LunrSearch
              setContextValues={setContextValues}
              menuLogo={menuLogo}
              isStartPage={isStartPage}
              logoUrl={logoUrl}
              closeMenu={closeMenu}
            />
          </div>
        </FullPageOverlay>
      )}
    </>
  );
};

export default HeaderOverlays;
