import { useShopServiceCartContext, useStaticConfigContext } from "@/core/contexts";
import Cart, { CartProps } from "./cart";

import { useCartItemsFromCartResponse } from "@/core/hooks";

export type ShopServiceCartProps = Pick<
  CartProps,
  | "onGoToCheckout"
  | "onContinueShopping"
  | "hideContinueShopping"
  | "hideGoToCheckout"
  | "hideHeadline"
  | "hideTotalSum"
  | "enableBlackWeekOffer"
  | "innerWrapperClassName"
  | "hideShippingProducts"
>;

export const ShopServiceCart = (props: ShopServiceCartProps) => {
  const {
    data: cart,
    error: cartError,
    isLoading,
    removeCartItem,
    updateCartItemQuantity,
  } = useShopServiceCartContext();

  const products = useCartItemsFromCartResponse(cart?.cartItems, cart) ?? [];
  const { eCommerce } = useStaticConfigContext();

  return (
    <Cart
      {...props}
      checkoutUrl={eCommerce.shopServicePaymentSlug}
      isDisabled={isLoading}
      totalSumInclVat={cart?.cartPrice.amount.amountIncludingVat ?? 0}
      originalProductSummaryAmount={cart?.cartPrice.amountBeforeDiscounts?.amountIncludingVat}
      products={products ?? []}
      deleteCartItem={(item) => removeCartItem(item.id)}
      updateCartItemQuantity={(item, quantity) => updateCartItemQuantity(item.id, quantity)}
    />
  );
};
