import { MouseEventHandler, useState } from "react";
import styles from "./language-selector.module.less";
import { GhostButton } from "@/core/components/primitives/parks-button/parks-button";
import { HorizontalContentPosition, Modal } from "@/core/components/primitives/modal/modal";
import Link from "@/core/components/primitives/link/link";
import { Locale, multipleClassNames } from "@/core/helpers";
import { useCurrentContentPageSlugsContext } from "@/core/contexts";
import Icon, { iconMap } from "@/core/components/primitives/icon/icon";
import { Language } from "@/core/components/modules/header/header-types";
import { useTranslation } from "react-i18next";
import { useContentContainerRef } from "@/core/components/primitives/content-container/content-container";
import { AnimatePresence } from "framer-motion";

const languageButtonStyles = [styles.languageButton, "waves-effect"];

const iconForLocale = (locale: Locale) => {
  const flag = `flag-${locale}` as const;
  // This check is mostly for cases where we have a locale that doesn't have a flag, such as Norwegian
  const icon = flag && flag in iconMap ? flag : "globe";
  return icon;
};

type ModalPosition = Exclude<HorizontalContentPosition, "center">;

export type LanguageSelectorProps = {
  locales: Array<Language>;
  /** modalPosition defaults to left, and is not relevant on mobile devices, as it is fullwidth */
  modalPosition?: ModalPosition;
  portalId?: string;
  /** Callback for when the selector is clicked */
  onSelectorOpen?: MouseEventHandler<HTMLButtonElement> | (() => void);
  /** Clicked slug is only used to determine which language was selected in Storybook */
  onSelectorClose: (clickedSlug?: string) => void;
};
export const LanguageSelector = ({
  locales,
  portalId,
  modalPosition = "left",
  onSelectorOpen,
  onSelectorClose,
}: LanguageSelectorProps) => {
  const { t } = useTranslation();

  const [isVisible, setIsVisible] = useState(false);
  const wrapperElement = useContentContainerRef();

  const getHash = () => {
    if (typeof window !== "undefined") {
      return window.location.hash;
    }
    return undefined;
  };

  const openSelector = (e: React.MouseEvent<HTMLButtonElement>) => {
    setIsVisible(true);
    onSelectorOpen?.(e);
  };

  const closeSelector = (clickedSlug?: string) => {
    setIsVisible(false);
    onSelectorClose(clickedSlug);
  };

  const { slugs, currentLocale } = useCurrentContentPageSlugsContext();
  const languageStringByCurrentLocale =
    locales.find((locale) => locale.locale === currentLocale)?.title || currentLocale;

  if (locales.length < 2) {
    return null;
  }

  return (
    <>
      <GhostButton
        iconLeftNew={iconForLocale(currentLocale)}
        className={multipleClassNames(...languageButtonStyles)}
        iconSize="s"
        label={currentLocale}
        ariaLabel={t("languagePickerButton", [languageStringByCurrentLocale])}
        onClick={openSelector}
      />
      <AnimatePresence>
        {isVisible && (
          <Modal
            isOpen={isVisible}
            onClose={closeSelector}
            id="language-selection"
            verticalContentPosition="top"
            horizontalContentPosition={modalPosition}
            portalId={portalId}
            refWrapperElement={portalId ? undefined : wrapperElement ?? undefined}
          >
            <nav className={styles.listWrapper}>
              <ul>
                {locales.map((locale) => {
                  const specificSlug = slugs[locale.locale];
                  const url = (specificSlug ?? locale.url) + getHash();

                  return (
                    <li role="none" key={`${url} : ${locale.title}`}>
                      <Link
                        role="listitem"
                        internalLink={url}
                        className={styles.link}
                        onClick={() => closeSelector(url)}
                        lang={locale.locale}
                      >
                        <Icon name={iconForLocale(locale.locale)} size="s" />
                        <span className={multipleClassNames(locale.locale === currentLocale && "bold")}>
                          {locale.title}
                        </span>
                      </Link>
                    </li>
                  );
                })}
              </ul>
            </nav>
          </Modal>
        )}
      </AnimatePresence>
    </>
  );
};
