import styles from "./header-actions.module.less";
import { LanguageSelector } from "@/core/components/modules/language-selector/language-selector";
import { GhostButton } from "@/core/components/primitives/parks-button/parks-button";
import { EventAggregator, SessionStorageHelper, isShippingFeeProduct, multipleClassNames } from "@/core/helpers";
import Link from "@/core/components/primitives/link/link";
import { Language } from "@/core/components/modules/header/header-types";
import { useShopServiceCartContext } from "@/core/contexts";
import { motion } from "framer-motion";
import { useTranslation } from "react-i18next";
import { MouseEventHandler, useEffect, useState } from "react";
import { useProducts } from "@/core/hooks/product-hooks";

const menuIconStyles = [styles.iconButton, "waves-effect"];

/** Renders the site logo. */
const HeaderLogo = ({
  siteName,
  logoUrl,
  logoImageUrl,
}: {
  siteName: string;
  logoUrl?: string;
  logoImageUrl?: string;
}) => (
  <div className={styles.logoWrapper}>
    <Link internalLink={logoUrl} className={styles.logoLink}>
      {logoImageUrl && (
        <div className={styles.logo}>
          <img className={styles.logoImage} src={logoImageUrl} alt={siteName} />
        </div>
      )}
    </Link>
  </div>
);

type CartState = {
  initial: boolean;
  totalItems: number | undefined;
};

/** Hook to get the cart state from either the Norce or ShopService context. */
const useCartState = () => {
  const { cartId, data: cart } = useShopServiceCartContext();
  const [hadExistingCart] = useState(!!cartId);
  const [shopServiceState, setShopServiceState] = useState<CartState>({
    initial: true,
    totalItems: undefined,
  });

  const { productsById } = useProducts(cart?.cartItems.map((item) => item.productId) ?? []);

  const cartTotalItems = cart?.cartItems
    .filter((p) => !isShippingFeeProduct(productsById.get(p.productId)))
    .reduce((acc, item) => acc + item.quantity, 0);

  useEffect(() => {
    if (typeof cartTotalItems === "number") {
      setShopServiceState((prev) => ({
        // `initial` should be remain true if this is only the first fetch of an existing cart
        // If we had no existing cart, it should be false after any update to cartTotalItems
        // Any subsequent updates to cartTotalItems will set `initial` to false
        initial: hadExistingCart && prev.totalItems === undefined,
        totalItems: cartTotalItems,
      }));
    }
  }, [hadExistingCart, cartTotalItems]);

  return shopServiceState;
};

/** Renders the cart button. */
const CartButton = ({ onClick }: { onClick: MouseEventHandler<HTMLButtonElement> }) => {
  const { t } = useTranslation();
  const { initial, totalItems } = useCartState();
  const [shouldHideCartButton, setShouldHideCartButton] = useState<boolean>(false);

  useEffect(() => {
    // Use a timeout to ensure local storage is checked after the component mounts
    setTimeout(() => {
      // Check local storage for the hide cart button setting
      const hideCartButton = SessionStorageHelper.getItem("hideHeaderCart");
      hideCartButton && setShouldHideCartButton(true);
    }, 0);
  }, []);

  return (
    <div className={styles.cartIconWrapper} data-should-hide={shouldHideCartButton}>
      <GhostButton
        className={multipleClassNames(...menuIconStyles)}
        onClick={onClick}
        ariaLabel={t("openFullPageOverlay", [t("cart")])}
        iconCenterNew="cart"
        iconSize="xl"
      />
      {!!totalItems && (
        <motion.span
          key={totalItems + "top"}
          initial={{ scale: 0 }}
          animate={{ scale: [1, 1.5, 1] }}
          transition={{ duration: 0.6 }}
          className={multipleClassNames(styles.itemsInCart, styles.addItem, !initial && styles.addItem)}
        >
          {totalItems}
        </motion.span>
      )}
    </div>
  );
};

/** Renders language selector and the search, cart, and menu buttons. */
const HeaderActions = ({
  languageSelectionList,
  disableCart,
  closeMenu,
  toggleSearch,
  toggleCart,
  toggleMore,
  setActionButtonRef,
  siteName,
  logoUrl,
  logoImageUrl,
}: {
  languageSelectionList?: { languages: Language[] };
  disableCart: boolean;
  closeMenu: () => void;
  toggleSearch: () => void;
  toggleCart: (cartContext?: any) => void;
  toggleMore: () => void;
  setActionButtonRef: (actionButton: HTMLButtonElement | null) => void;
  siteName: string;
  logoUrl?: string;
  logoImageUrl?: string;
}) => {
  const { t } = useTranslation();

  const handleButtonClick =
    (label: string, passedButtonFunction?: () => void) => (e: React.MouseEvent<HTMLButtonElement>) => {
      setActionButtonRef(e.currentTarget);
      EventAggregator.publish("trackEvent", {
        category: "Header",
        action: "Opened",
        label: label,
      });
      passedButtonFunction?.();
    };

  return (
    <div className={styles.wrapper}>
      <div className={styles.leftWrapper}>
        {languageSelectionList?.languages && (
          <div className={styles.languageSelectorWrapper}>
            <LanguageSelector
              locales={languageSelectionList.languages}
              onSelectorOpen={handleButtonClick("Language Selector")}
              onSelectorClose={closeMenu}
            />
          </div>
        )}
        <div className={styles.search}>
          <GhostButton
            onClick={handleButtonClick("Search", toggleSearch)}
            label={t("search")}
            ariaLabel={t("openFullPageOverlay", [t("search")])}
            labelClass={styles.buttonLabel}
            iconLeftNew="search"
            iconSize="xl"
            className={multipleClassNames(...menuIconStyles)}
          />
        </div>
      </div>
      <HeaderLogo siteName={siteName} logoUrl={logoUrl} logoImageUrl={logoImageUrl} />
      <div className={styles.rightWrapper}>
        {!disableCart && <CartButton onClick={handleButtonClick("Cart", toggleCart)} />}
        <GhostButton
          className={multipleClassNames(...menuIconStyles)}
          onClick={handleButtonClick("Menu", toggleMore)}
          label={t("menu")}
          ariaLabel={t("openFullPageOverlay", [t("menu")])}
          labelClass={styles.buttonLabel}
          iconLeftNew="menu"
          iconSize="xl"
        />
      </div>
    </div>
  );
};

export default HeaderActions;
