import styles from "./site-menu.module.less";
import Link from "@/core/components/primitives/link/link";
import { LinkGroup } from "@/core/components/modules/header/header-types";
import { EventAggregator, multipleClassNames } from "@/core/helpers";
import { GatsbyImage, IGatsbyImageData } from "gatsby-plugin-image";

const SiteMenu = ({
  siteMenuLogo,
  siteName,
  isStartPage,
  logoUrl,
  hasBackgroundImage,
  loginLink,
  linkGroups,
  closeMenu,
}: {
  siteMenuLogo?: string | IGatsbyImageData;
  siteName: string;
  isStartPage: boolean;
  logoUrl?: string;
  hasBackgroundImage: boolean;
  loginLink?: JSX.Element;
  linkGroups?: LinkGroup[];
  closeMenu: () => void;
}) => (
  <div
    role="menu"
    data-add-gap={!siteMenuLogo}
    data-has-background-image={hasBackgroundImage}
    className={styles.siteMenuWrapper}
  >
    {siteMenuLogo && (
      <Link internalLink={isStartPage ? undefined : logoUrl} onClick={closeMenu} className={styles.siteMenuLogoLink}>
        {typeof siteMenuLogo !== "string" ? (
          <GatsbyImage className={styles.siteMenuLogo} image={siteMenuLogo} alt={siteName} />
        ) : (
          <img className={multipleClassNames(styles.siteMenuLogo, styles.fallback)} src={siteMenuLogo} alt={siteName} />
        )}
      </Link>
    )}
    {loginLink && <div className={styles.loginSection}>{loginLink}</div>}
    {linkGroups?.map((linkGroup) => (
      <div key={linkGroup.id} className={styles.linkGroup}>
        {linkGroup.headline && (
          <h4 className={multipleClassNames(styles.groupHeadline, "body-s")}>{linkGroup.headline}</h4>
        )}
        <ul className={styles.linkGroupList}>
          {linkGroup.listObjects.map((listItem) => (
            <Link
              role="listitem"
              key={listItem.id}
              contentfulLink={listItem}
              className={styles.listItemLink}
              onClick={() => {
                closeMenu();
                EventAggregator.publish("trackEvent", {
                  category: "Navigation",
                  action: "Clicked link",
                  label: listItem.title || "",
                });
              }}
            >
              <li role="none" className={multipleClassNames(styles.listItem, linkGroup.secondary ? "body-s" : "h5")}>
                {listItem.title}
              </li>
            </Link>
          ))}
        </ul>
      </div>
    ))}
  </div>
);

export default SiteMenu;
