import { useMemo } from "react";
import lunr, { Index } from "lunr";
import lunr_stemmer from "lunr-languages/lunr.stemmer.support";
import lunr_sv from "lunr-languages/lunr.sv";
import lunr_no from "lunr-languages/lunr.no";
import { Store } from "@/core/types";

lunr_stemmer(lunr);
lunr_sv(lunr);
lunr_no(lunr);

export const useLunr = <StoreItem>(query?: string, rawIndex?: string, rawStore?: Store<StoreItem>) => {
  const index = useMemo(() => {
    if (rawIndex === undefined || rawIndex === null) {
      return undefined;
    }

    return Index.load(JSON.parse(rawIndex));
  }, [rawIndex]);

  const store = useMemo(() => {
    return rawStore;
  }, [rawStore]);

  return useMemo(() => {
    if (!query || !index || !store) return [];

    const results = index.search(query);
    return results.map(({ ref }) => store[ref]);
  }, [query, index, store]);
};
