import styles from "./lunr-search.module.less";
import { useState, useEffect, useCallback } from "react";
import { debounce } from "lodash-es";
import { useLunr } from "@/core/hooks";
import { EventAggregator, LanguageHelper, SearchHelper, multipleClassNames } from "@/core/helpers";
import { Store } from "@/core/types";
import { ContextValues } from "@/core/components/modules/header/header-types";
import Link from "@/core/components/primitives/link/link";
import InputField from "@/core/components/primitives/input-field/input-field";
import { useTranslation } from "react-i18next";
import { SpokenText } from "@/core/components/primitives/spoken-text/spoken-text";
import { GatsbyImage, IGatsbyImageData } from "gatsby-plugin-image";

const searchPageviewDebounced = debounce((query: string) => {
  EventAggregator.publish("trackPageview", {
    virtualPagePath: "/search?q=" + query,
    virtualPageTitle: "Searched for " + query,
  });
}, 1000);

export type StoreItem = {
  id: string;
  title: string;
  slug: string;
};

type Props = {
  setContextValues: (values: Partial<ContextValues>) => void;
  menuLogo?: string | IGatsbyImageData;
  isStartPage: boolean;
  logoUrl?: string;
  closeMenu: () => void;
};

export default function LunrSearch(props: Props) {
  const [queryString, setQueryString] = useState("");
  const [query, setQuery] = useState<string | undefined>(undefined);
  const [index, setIndex] = useState<string | undefined>(undefined);
  const [store, setStore] = useState<Store<StoreItem> | undefined>(undefined);

  const { t } = useTranslation();
  const results = useLunr<StoreItem>(query, index, store);
  const filteredResults = results.filter((page) => page.slug).slice(0, 10);
  const [debouncedResultCount, setDebouncedResultCount] = useState(0);

  const updateResultCount = useCallback(
    debounce((count: number) => {
      setDebouncedResultCount(count);
    }, 2_000),
    [],
  );

  useEffect(() => {
    updateResultCount(filteredResults.length);
  }, [filteredResults.length, updateResultCount]);

  const { menuLogo, isStartPage, logoUrl, closeMenu } = props;

  useEffect(() => {
    SearchHelper.getSingelton<StoreItem>()
      .getLunrData(LanguageHelper.getCurrentLocale())
      .then(({ index, store }) => {
        setIndex(index);
        setStore(store);
      });
  }, []);

  const onClickLink = () => {
    closeMenu();
    searchPageviewDebounced.flush();
  };

  const handleQueryStringChange = (e: string) => {
    setQueryString(e);

    const queryStrings = e
      .toLowerCase()
      .split(" ")
      .filter((item) => item.length > 1);

    if (queryStrings.length === 0 && !filteredResults.length) {
      return;
    }

    // https://lunrjs.com/guides/searching.html
    const query = queryStrings
      .map((item) => `title:${item}^100 title:*${item}*^30 keywords:${item}^30 keywords:*${item}*^5`)
      .join(" ");

    setQuery(query);
    searchPageviewDebounced(e);
  };

  return (
    <div className={styles.searchWrapper} data-add-gap={!menuLogo}>
      <div className={multipleClassNames("block--max-width-narrow", styles.searchContent)}>
        <search className={styles.search}>
          <InputField
            name="search"
            icon="search"
            type="search"
            value={queryString}
            onChange={(name: string, value: string) => handleQueryStringChange(value)}
            placeholder={t("searchPlaceHolder")}
            className={styles.inputWrapper}
            inputClassName={styles.inputField}
          />
          <SpokenText text={t("searchResultCount", { count: debouncedResultCount })} ariaLive="polite" />
          {(queryString.length > 1 || filteredResults.length > 0) && (
            <h6 className={multipleClassNames(styles.listItemHeading)} data-contentful-label-id="searchResultHeading">
              {t("searchResultHeading")}
            </h6>
          )}
          <ul
            className={multipleClassNames(
              styles.list,
              queryString.length > 1 && styles.listActive,
              "block--max-width-narrow",
            )}
            aria-label={t("searchResultHeading")}
          >
            {filteredResults.map((page) => (
              <li className={styles.listItem} key={page.title + page.id}>
                <Link
                  internalLink={page.slug}
                  className={multipleClassNames(styles.listItemUrl, "body-s")}
                  onClick={() => onClickLink()}
                >
                  {page.title}
                </Link>
              </li>
            ))}
            {queryString.length > 1 && results.length === 0 && (
              <li
                className={multipleClassNames(styles.listItem, styles.noResult)}
                key="no_search_result"
                data-contentful-label-id="searchNoSearchResultText"
              >
                {t("searchNoSearchResultText")}
              </li>
            )}
          </ul>
        </search>
      </div>
      {menuLogo && (
        <Link internalLink={isStartPage ? undefined : logoUrl} onClick={closeMenu} aria-label={t("backToLandingPage")}>
          {typeof menuLogo !== "string" ? (
            <GatsbyImage className={styles.menuLogo} image={menuLogo} alt={t("image")} />
          ) : (
            <img className={multipleClassNames(styles.menuLogo, styles.fallback)} src={menuLogo} alt={t("image")} />
          )}
        </Link>
      )}
    </div>
  );
}
